def sh(*a): return subprocess.run(a,capture_output=True,text=True).stdout
prs=json.loads(sh('gh','pr','list','--state','open','--limit','60','--json','number,headRefName,baseRefName'))
seen={}
for p in sorted(prs,key=lambda x:x['number']):
    base='origin/'+p['baseRefName']; head='origin/'+p['headRefName']
    for f in sh('git','diff','--name-only','--diff-filter=A',base+'...'+head,'--','.changeset').split():
        if not f.endswith('.md') or f.endswith('README.md'): continue
        txt=sh('git','show',f'{head}:{f}')
        seen.setdefault(f,(p['number'],txt))
issues=0
for f,(n,txt) in sorted(seen.items(), key=lambda x:x[1][0]):
    m=re.match(r'---\n(.*?)\n---\n(.*)',txt,re.S)
    if not m: print(n,f,'NO FRONTMATTER'); continue
    fm,body=m.group(1).strip(),m.group(2).strip()
    lines=body.split('\n'); probs=[]
    if re.match(r'^(#|[-*] |\d+\. )',body): probs.append('starts with heading/list marker')
    if len(lines)>1: probs.append(f'{len(lines)} lines (hard-wrapped or multi-paragraph/list)')
    if any(re.match(r'^\s*([-*]|\d+\.) ',l) for l in lines): probs.append('contains list')
    if len(body)>420: probs.append(f'long ({len(body)} chars)')
    if re.search(r'`[a-z_]+::|\bfn \b|\.rs\b|\bPR #|\btrail\b|SPEC-|crates/',body): probs.append('internal jargon/paths')
    tag='  ' if not probs else '!!'
    print(tag,f'#{n}',f.split('/')[-1],'|',fm.replace('\n',' ; ')[:90],'|',len(body),'chars', '; '.join(probs))
print(len(seen),'changesets')
json.dump({f:v for f,v in seen.items()},open('/tmp/claude-501/findings/changesets.json','w'))
EOF

