allpr=json.loads(sh('gh','pr','list','--state','all','--limit','400','--json','number,headRefName,state'))
prs={}
for p in allpr: prs.setdefault(p['headRefName'],[]).append((p['number'],p['state']))
heads=[l.split('refs/heads/')[1] for l in sh('git','ls-remote','--heads','origin').splitlines()]
rows=[]
for b in sorted(heads):
    if b=='main' or b in op: continue
    ref='origin/'+b
    merged = subprocess.run(['git','merge-base','--is-ancestor',ref,'origin/main']).returncode==0
    ahead=sh('git','rev-list','--count',f'origin/main..{ref}')
    last=sh('git','log','-1','--format=%cs %s',ref)[:70]
    rows.append((b,merged,ahead,prs.get(b,[]),last))
print(len(rows),'non-open-PR branches')
for grp,title in ((lambda r:r[1],'FULLY MERGED into main (safe to delete)'),(lambda r:not r[1] and any(s=='MERGED' for _,s in r[3]),'PR merged but branch has extra commits (squash/rebase or later work)'),(lambda r:not r[1] and not any(s=='MERGED' for _,s in r[3]),'NOT merged, no merged PR (review before deleting)')):
    print('\n##',title)
    for r in rows:
        if grp(r): print(f"  {r[0][:48]:48} ahead={r[2]:>3} PRs={[f'#{n}:{s[0]}' for n,s in r[3]]} | {r[4]}")
EOF

