n=$(gh pr list --head feat/construct-suite --json number --jq '.[0].number'); echo PR $n; python3 -I - <<'EOF'
import json
p='/private/tmp/claude-501/-Users-gabe-Projects-caliper/ad4b3461-bb6f-49f0-bb4d-997d9b8887ba/tasks/wkoj1scu1.output'
t=open(p).read()
i=t.find('{"harness"')
try:
    d=json.loads(t[i:t.rfind('}')+1])
except Exception as e:
    # fall back to journal
    d=None
if d is None:
    import glob
    for line in open('/Users/gabe/.claude/projects/-Users-gabe-Projects-caliper/ad4b3461-bb6f-49f0-bb4d-997d9b8887ba/subagents/workflows/wf_8c393ec3-3ae/journal.jsonl'):
        r=json.loads(line)
        v=r.get('result') or r.get('value')
        if isinstance(v,dict) and 'gaps' in v: d={'integrated':v}
g=d['integrated']['gaps']
print(len(g),'gaps; invalid',d['integrated'].get('invalid'))
from collections import defaultdict
by=defaultdict(list)
for x in g: by[x['verdict']].append(x)
for v,xs in by.items():
    print('==',v,len(xs))
    for x in xs[: (6 if v!='wrong' else 10)]: print('  ',x['row'],'|',x['why'][:150])
EOF

